        "pack-box",
        "ship-box"
      ],
      "terms": [
        "Box"
      ],
      "heuristics_applied": [
        "actor",
        "pivotal-event"
      ],
      "rationale": "Warehouse process"
    }
  ],
  "bounded_contexts": [
    {
      "id": "subscriptions",
      "name": "Subscriptions",
      "subdomains": [
        "subscriptions"
      ],
      "owns_events": [
        "subscription-started",
        "meals-chosen",
        "subscription-teleported"
      ],
