      "independent_service_check": {
        "sense_check": "yes",
        "brand": "yes",
        "revenue": "yes",
        "cost_tracking": "yes",
        "data": "yes",
        "user_personas": "yes",
        "cognitive_load": "yes",
        "verdict": "candidate"
      },
      "rationale": "Core"
    },
    {
      "id": "billing",
      "name": "Billing",
      "subdomains": [
        "billing"
      ],
      "owns_events": [
        "week-charged"
      ],
      "owns_commands": [
        "charge-week",
        "charge-card"
      ],
      "owns_aggregates": [],
      "terms": [],
